const DEMO = {
  dirs: ["meta/xEdit/modgroups", "__MACOSX", "ModOrganizer_logs"],
  files: [
    ["meta.ini", 1.2], [".DS_Store", 6.1], ["textures/armor.psd", 48200], ["textures/armor.xcf", 31400],
    ["plugins/Patch.esp.bak", 220], ["plugins/Patch.esp.copy", 220], ["docs/Lisez-moi.doc", 84],
    ["docs/LICENSE.rtf", 12], ["Thumbs.db", 18], ["meshes/sword.nif.mohidden", 3]
  ]
};

const $ = (id) => document.getElementById(id);
let lang = localStorage.getItem("fc_lang") || "fr";
let folder = "";
let busy = false;

const fmt = (s, o) => s.replace(/\{(\w+)\}/g, (_, k) => o[k]);
const size = (kb) => kb >= 1024 ? (kb / 1024).toFixed(2) + " Mo" : kb.toFixed(1) + " Ko";
const log = (html) => { const l = $("log"); l.insertAdjacentHTML("beforeend", html + "\n"); l.scrollTop = l.scrollHeight; };
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

function render() {
  const t = T[lang];
  document.title = t.title; $("wtitle").textContent = t.title;
  $("title").textContent = t.header; $("subtitle").textContent = t.sub;
  $("path").placeholder = t.ph; $("browse").textContent = t.browse;
  $("logTitle").textContent = t.logTitle; $("rules").textContent = t.rules;
  $("scan").textContent = t.scan; $("clean").textContent = t.clean;
  $("status").textContent = folder ? t.loaded : t.ready;
  $("dTitle").textContent = t.dHeader; $("dClose").textContent = t.close;
  $("rulesBody").innerHTML = `
    <h3>${t.h1}</h3><ul><li><code>.DS_Store</code></li><li><code>Thumbs.db</code></li><li><code>__MACOSX</code></li></ul>
    <h3>${t.h2}</h3><ul><li><code>*.bak</code></li><li><code>*.copy</code></li></ul>
    <h3>${t.h3}</h3><ul><li><code>meta.ini</code></li><li><code>*.mohidden</code></li><li><code>xEdit/modgroups</code></li></ul>
    <h3>${t.h4}</h3><ul><li><code>*.doc</code> <code>*.rtf</code></li><li><code>*.pdn</code> <code>*.xcf</code> <code>*.psd</code></li></ul>
    <div class="note">${t.note}</div>`;
  document.querySelectorAll(".seg").forEach((b) => b.classList.toggle("checked", b.dataset.lang === lang));
}

function setBusy(v) {
  busy = v;
  ["path", "browse", "rules", "scan", "clean"].forEach((id) => ($(id).disabled = v));
  document.querySelectorAll(".seg").forEach((b) => (b.disabled = v));
}

async function run(clean) {
  const t = T[lang];
  if (!folder) { alert(lang === "fr" ? "Veuillez désigner un dossier existant valide." : "Please select a valid existing folder."); return; }
  if (clean && !confirm(t.confirm)) return;
  setBusy(true);
  $("log").innerHTML = "";
  $("status").textContent = fmt(t.proc, { m: clean ? t.modeClean : t.modeSim });
  log("=".repeat(56));
  log(`${t.target} ${folder}`);
  log(`${t.mode} ${clean ? t.modeClean : t.modeSim}`);
  log("=".repeat(56));
  let total = 0;
  for (const d of DEMO.dirs) { await sleep(120); log(`${clean ? t.tagDirDel : t.tagDir} ${folder}/${d}`); }
  for (const [f, kb] of DEMO.files) { await sleep(120); total += kb; log(`${clean ? t.tagDel : t.tagDet} ${folder}/${f} (${size(kb)})`); }
  log("");
  log(fmt(t.summary, { f: DEMO.files.length, d: DEMO.dirs.length }));
  log(`<b>${size(total)}</b>`);
  const done = fmt(clean ? t.cleanDone : t.simDone, { f: DEMO.files.length, d: DEMO.dirs.length });
  log(done);
  if (!clean) log(t.hint);
  $("status").textContent = done;
  setBusy(false);
}

document.querySelectorAll(".seg").forEach((b) =>
  b.addEventListener("click", () => { lang = b.dataset.lang; localStorage.setItem("fc_lang", lang); render(); }));
$("browse").addEventListener("click", () => {
  const v = prompt(T[lang].ph, "/Volumes/SKYRIM/Skyrim/Instance");
  if (v && v.trim()) { folder = v.trim(); $("path").value = folder; $("log").innerHTML = ""; log(T[lang].sel + folder); render(); }
});
$("path").addEventListener("input", (e) => { folder = e.target.value.trim(); render(); });
$("rules").addEventListener("click", () => $("overlay").classList.add("open"));
$("dClose").addEventListener("click", () => $("overlay").classList.remove("open"));
$("overlay").addEventListener("click", (e) => { if (e.target.id === "overlay") $("overlay").classList.remove("open"); });
$("scan").addEventListener("click", () => run(false));
$("clean").addEventListener("click", () => run(true));
render();
